function CatHouseExploreMgr:InitServiceData()
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    local serviceData = checkTable(catHouseHomeDojo.exploreList)
    if isNull(self.listTaskData) then
        self.listTaskData = {}
    end
    for i, data in pairs(serviceData) do
        local taskData = ExploreServiceTask.New(data)
        table.insert(self.listTaskData, taskData)
        taskData.timerRemain = self:SetTimer(taskData.remainTime,nil, function()
            self:ActionOnRemoveRemain(taskData)
        end)
        taskData.timerRefreshRemain = self:SetTimer(taskData.refreshRemainTime, nil, function() 
            self:ActionOnRemoveRefreshRemain(taskData)
        end)
        local taskStatus = self:GetCellStatus(taskData)
        taskData.status = taskStatus
    end
    table.sort(self.listTaskData, function(a, b)
        return a.exploreId < b.exploreId
    end)
    local exploreNextRefreshTimesSeconds = checkNumber(catHouseHomeDojo.exploreNextRefreshTimesSeconds)
    if exploreNextRefreshTimesSeconds > 0 then
        self.timerTaskRefresh = self:SetTimer(exploreNextRefreshTimesSeconds, nil, function() 
            self.timerTaskRefresh = nil
            self:HandleTimerTaskRefresh()
        end)
    end
    print("->CatHouseExploreMgr:InitServiceData", table.dump(self.listTaskData))
end

---@param taskData table
---@return integer
function CatHouseExploreMgr:GetCellStatus(taskData)
    local teamCats = checkTable(taskData.teamCats)
    local remainTime = checkInt(taskData.remainTime)
    local refreshRemainTime = checkInt(taskData.refreshRemainTime)
    print("->CatHouseExploreMgr:GetCellStatus_exploreId_teamCats_remainTime_refreshRemainTime", checkNumber(taskData.exploreId), table.dump(checkTable(teamCats)), remainTime, refreshRemainTime)
    if #teamCats <= 0 and remainTime <= 0 and refreshRemainTime <= 0 then
        return self.ENUM_TASK_STATUS.NOT_START
    elseif #teamCats <= 0 and remainTime <= 0 and refreshRemainTime > 0 then
        return self.ENUM_TASK_STATUS.REFRESH_WAIT
    elseif #teamCats > 0 and remainTime > 0 then
        return self.ENUM_TASK_STATUS.DURING
    elseif #teamCats > 0 and remainTime <= 0 then
        return self.ENUM_TASK_STATUS.FINISH
    end
    return nil
end

