function CatHouseExploreMgr:CatHouseExploreStartReq(pExploreId, pTeamCats, cb)
    print("->CatHouseExploreMgr:CatHouseExploreStartReq:", pExploreId, pTeamCats, cb)
    GameUtils.Request(Interfaces.CatHouseExploreStart, {exploreId = checkInt(pExploreId), teamCats = checkString(pTeamCats)}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local data    = response.data or {}
        local rewards = data.rewards
        self:CatListStart(pExploreId)
        if cb then cb(rewards) end
    end)
end

function CatHouseExploreMgr:CatListStart(pExploreId)
    local exploreData = self:GetExploreData(pExploreId)
    local taskId = checkNumber(exploreData.taskId)
    local taskVo = self:GetCatHouseTaskData(taskId)
    local costHpCat = checkNumber(taskVo.strengthNum)
    local costHpPlayer = checkNumber(taskVo.playerStrengthNum)
    local taskTime = checkNumber(taskVo.taskTime)
    --- 更新猫的状态
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    if not isNull(self.listCatsTeam) then
        for i = 1, #self.listCatsTeam do
            local catData = self.listCatsTeam[i]
            catData.hp = checkNumber(catData.hp) - checkNumber(costHpCat)
            component:UpdateCDData(catData.id, ConstantsCatHouse.CatStatus.Exploring, checkNumber(taskTime))
        end
    end
    --- 更新玩家体力
    GoodsUtils.DrawRewards({
        [1] = {
            num = 0 - math.abs(checkNumber(costHpPlayer)),
            goodsId = 300004,
        }
    })
    --- 更新探险列表数据
    self:SetExploreTimerRemain(pExploreId, taskTime,nil,nil)
    print("->CatTeam_CatHouseExploreMgr:CatListStart", checkTable(CatHouseExploreMgr:GetListCatsTeamIdExploreStart()))
    exploreData.teamCats = checkTable(CatHouseExploreMgr:GetListCatsTeamIdExploreStart())
    exploreData.status = self:GetCellStatus(exploreData)
end

function CatHouseExploreMgr:CatHouseExploreCancelReq(pExploreId, cb)
    GameUtils.Request(Interfaces.CatHouseExploreCancel,{exploreId = pExploreId}, function(request, response)
        print("->CatHouseExploreMgr:CatHouseExploreRefresh:", table.dump(checkTable(response)))
        if checkNumber(response.errCode) ~= 0 then return end
        local data = checkTable(response.data)
        local refreshRemainTime = checkNumber(data.refreshRemainTime)
        local taskId = checkNumber(data.taskId)
        local require = checkTable(data.require)
        local exploreData = {
            exploreId = pExploreId,
            taskId = taskId,
            require = require,
            teamCats = {},
            remainTime = 0,
            refreshRemainTime = refreshRemainTime,
            timerRemain = nil,
            timerRefreshRemain = self:SetTimer(refreshRemainTime, nil, nil),
            status = self.ENUM_TASK_STATUS.REFRESH_WAIT, }
        self:SetExploreData(pExploreId, exploreData)
        if cb then cb(clone(exploreData)) end
    end)
end

function CatHouseExploreMgr:CatHouseExploreEndReq(pExploreId, cb)
    GameUtils.Request(Interfaces.CatHouseExploreEnd, {exploreId = pExploreId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        ---探索任务结束奖励列表
        local jsonData = response.data

        --更新奖励
        local rewardData = checkTable(jsonData.rewards)
        GoodsUtils.DrawRewards(rewardData)
        
        xTry(function()
            local mainExp = checkNumber(jsonData.mainExp)
            local playerLv = checkNumber(jsonData.playerLv)
            --更新经验
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComponent:UpdatePlayerLvMainExp(playerLv, mainExp)
            --- 更新体力
            local hp = checkNumber(jsonData.hp)
            GoodsUtils.DrawRewards({
                { num = checkNumber(hp) - GoodsUtils.GetThingNo(Constants.Currency.HpId),
                    goodsId = Constants.Currency.HpId }})
        end)
        
        local taskId = checkInt(jsonData.taskId)
        local require = checkTable(jsonData.require)
        
        local exploreEndData = {
            rewardData = rewardData,
            taskId = taskId,
            require = require,
        }
        
        if cb then cb(clone(exploreEndData)) end
    end)
end

function CatHouseExploreMgr:CatHouseExploreRefresh(pExploreId, cb)
    GameUtils.Request(Interfaces.CatHouseExploreRefresh,{exploreId = pExploreId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local data = checkTable(response.data)
        local taskId = checkNumber(data.taskId)
        local require = checkTable(data.require)
        local exploreData = {
            exploreId = pExploreId,
            taskId = taskId,
            require = require,
            teamCats = {},
            remainTime = 0,
            refreshRemainTime = 0,
            timerRemain = nil,
            timerRefreshRemain = nil,
            status = self.ENUM_TASK_STATUS.NOT_START, }
        self:SetExploreData(pExploreId, exploreData)
        --- 更新刷新次数
        local catHouseHomeDojo = self:GetCatHouseHomeDojo()
        local taskRefreshTimes = checkNumber(catHouseHomeDojo.exploreRefreshTimes)
        self:UpdateTaskRefreshTimes(taskRefreshTimes - 1)
        --- 更新次数刷新计时器
        if IsNull(self.timerTaskRefresh) then
            self:SetTimerTaskRefresh()
        end
        ---更新ExploreCell状态
        self:CleanExploreRefreshRemainTimer(pExploreId)
        Events.Broadcast(Constants.EventNames.CatHouseExploreTaskRefreshUpdate)
        ---探索任务结束奖励列表
        if cb then cb() end
    end)
end

function CatHouseExploreMgr:CatHouseExploreRefreshTimesBuy(cb)
    GameUtils.Request(Interfaces.CatHouseExploreRefreshTimesBuy, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
       self:CostGoods(self.EXPLORE_REFRESH_GOODS_ID, self.EXPLORE_REFRESH_GOODS_NUM)
