function CatHouseExploreMgr:CostGoods(goodsId, goodsNum)
    goodsId = checkNumber(goodsId)
    goodsNum = checkNumber(goodsNum)
    local goodsNumPlayer = GoodsUtils.GetThingNo(goodsId)
    if goodsNumPlayer < goodsNum then
        --todo 现在只有一种货币
        ---@type StoreUtils
        local storeUtils = import('Game.UI.Store.StoreUtils')
        ---@type StoreConstants
        local StoreConstants = import('Game.UI.Store.StoreConstants')
        storeUtils.OpenStore(StoreConstants.OpenIds.StoreFreeDiamond)
    else
        ---花费货币
        GoodsUtils.DrawRewards({
            [1] = {
                num = 0 - math.abs(goodsNum),
                goodsId = goodsId, }
        })
    end
end

function CatHouseExploreMgr:CatHouseDrawExploreBox(cb)
    GameUtils.Request(Interfaces.CatHouseDrawExploreBox, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = checkTable(response.data)
        local rewardData = checkTable(jsonData.rewards)--rewards_list_奖励列表
        local boxId = checkNumber(jsonData.boxId)--boxId_int_探索宝箱ID
        local boxStar = checkNumber(jsonData.boxStar)
        GoodsUtils.DrawRewards(rewardData)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData } })
        self:UpdateExploreBoxData(boxId)--todo 等待服务器修改数据结构
        self:UpdateExploreBoxStars(boxStar) --进度清零
        if cb then cb(clone(rewardData)) end
    end)
end

