function CatHouseExploreMgr:UpdateTaskRefreshTimes(value)
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    catHouseHomeDojo.exploreRefreshTimes = checkNumber(value) <= 0 and 0 or checkNumber(value)
    if (catHouseHomeDojo.exploreRefreshTimes >= self.EXPLORE_REFRESH_TIME_MAX) 
            and (not isNull(self.timerTaskRefresh)) then
        self:CleanTimerTaskRefresh()
        catHouseHomeDojo.exploreNextRefreshTimesSeconds = 0
    end
end

