---@param timeCount integer
---@param CBRunning fun(count:integer):void
---@param CDFinish fun():void
---@return Engine.Modules.CDTimerModule
function CatHouseExploreMgr:SetTimer(timeCount, CBRunning, CDFinish)
    if isNull(timeCount) or timeCount <= 0 then return nil end
    local timer = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if count <= 0 then   -- 结束
            CDTimerModule.GetInstance():RemoveCD(timer)
            timer = nil
        else
            if CBRunning then CBRunning(count) end
        end
    end, math.abs(timeCount), false, true, true)
    timer.OnRemove = CDFinish
    return timer
end

function CatHouseExploreMgr:ActionOnRemoveRemain(exploreData)
    local exploreId = checkNumber(exploreData.exploreId)
    if isNull(self:GetExploreData(exploreId)) then return end
    exploreData.remainTime = 0
    exploreData.status = self:GetCellStatus(exploreData)
end

function CatHouseExploreMgr:ActionOnRemoveRefreshRemain(exploreData)
    local exploreId = checkNumber(exploreData.exploreId)
    if isNull(self:GetExploreData(exploreId)) then return end
    exploreData.refreshRemainTime = 0
    exploreData.status = self:GetCellStatus(exploreData)
end

function CatHouseExploreMgr:CleanExploreRemainTimer(exploreId)
    local explore = self:GetExploreData(exploreId)
    if isNull(explore) then return end
    explore.remainTime = 0
    local timerRemain = explore.timerRemain
    if not isNull(timerRemain) then
        CDTimerModule.GetInstance():RemoveCD(timerRemain)
        explore.timerRemain = nil
    end
end

function CatHouseExploreMgr:CleanExploreRefreshRemainTimer(exploreId)
    local explore = self:GetExploreData(exploreId)
    if isNull(explore) then return end
    explore.refreshRemainTime = 0
    local timerRefreshRemain = explore.timerRefreshRemain
    if not isNull(timerRefreshRemain) then
        CDTimerModule.GetInstance():RemoveCD(timerRefreshRemain)
        explore.timerRefreshRemain = nil
    end
end

function CatHouseExploreMgr:CleanTimer()
    for i = 1, #self.listTaskData do
        local exploreData =  self.listTaskData[i]
        local exploreId = exploreData.exploreId
        self:CleanExploreRemainTimer(exploreId)
        self:CleanExploreRefreshRemainTimer(exploreId)
    end
    self:CleanTimerTaskRefresh()
end

function CatHouseExploreMgr:CleanTimerTaskRefresh()
    if not isNull(self.timerTaskRefresh) then
        self.timerTaskRefresh.OnCd = nil
        self.timerTaskRefresh.OnRemove = nil
        CDTimerModule.GetInstance():RemoveCD(self.timerTaskRefresh)
        self.timerTaskRefresh = nil
    end
end
