    local taskVo = self:GetCatHouseTaskData(taskId)
    local conditionDesc = taskVo.attributeNumDesc
    
    local num_1 = taskVo.attributeNumOne
    local award_1 = taskVo.awardOneId
    local awardNum_1 = taskVo.awardOneNum
    self:InsertCondition(listResult, num_1, award_1, awardNum_1, conditionDesc)
    
    local num_2 = taskVo.attributeNumTwo
    local award_2 = taskVo.awardTwoId
    local awardNum_2 = taskVo.awardTwoNum
    self:InsertCondition(listResult, num_2, award_2, awardNum_2, conditionDesc)
    
    local num_3 = taskVo.attributeNumThree
    local award_3 = taskVo.awardThreeId
    local awardNum_3 = taskVo.awardThreeNum
    self:InsertCondition(listResult, num_3, award_3, awardNum_3, conditionDesc)

    local num_4 = taskVo.attributeNumFour
    local award_4 = taskVo.awardFourId
    local awardNum_4 = taskVo.awardFourNum
    self:InsertCondition(listResult, num_4, award_4, awardNum_4, conditionDesc)
    
    local num_5 = taskVo.attributeNumFive
    local award_5 = taskVo.awardFiveId
    local awardNum_5 = taskVo.awardFiveNum
    self:InsertCondition(listResult, num_5, award_5, awardNum_5, conditionDesc)
    return listResult
end

function CatHouseExploreMgr:GetTaskExtraCondition(taskId)
    local listResult = {}
    local taskVo = self:GetCatHouseTaskData(taskId)
    
    local num_1 = taskVo.requireOne
