end

function CatHouseExploreMgr:GetExtraConditionDesc(desc, requireId, value)
    print("->CatHouseExploreMgr:GetExtraConditionDesc", desc, requireId, value)
    local targetDesc = self:TaskExtraConditionTranslator(requireId, value)
    return checkString(string.gsub(desc, "_target_id_", targetDesc))
end

function CatHouseExploreMgr:TaskExtraConditionTranslator(requireId, value)
    requireId = checkNumber(requireId)
    if requireId == ExploreExtraType.CatType then
        local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", checkNumber(value))
        if not isNull(catHouseCatVo) then
            return checkString(catHouseCatVo.name)
        end
    elseif requireId == ExploreExtraType.SpecifyBasic or requireId == ExploreExtraType.SpecifyCombination then
        local catHouseCatDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", value)
        if not isNull(catHouseCatDataVo) then
            return checkString(catHouseCatDataVo.name)
        end
    end
    return ""
end

function CatHouseExploreMgr:GetExploreRequireData(exploreId)
    for i, data in pairs(self.listTaskData) do
        if data.exploreId == checkNumber(exploreId) then
            return checkTable(data.require)
        end
    end
    return nil
end

function CatHouseExploreMgr:GetRequireDataByIndex(servicesData, taskId)
    local result = {}
    local configData = self:GetTaskExtraCondition(checkNumber(taskId))
    for i, data in pairs(configData) do
        result[i] = { type = data.numLevel, value = servicesData[checkString(i)] }
    end
    --print("->CatHouseExploreMgr:GetRequireDataByIndex_RequireData:", table.dump(result))
    return result
end

function CatHouseExploreMgr:CheckCatsListHadExtraCondition(catIdList, exploreId, taskId)
    local extraCondition = checkTable(self:GetRequireDataByIndex(checkTable(self:GetExploreRequireData(exploreId)), checkNumber(taskId)))
    local catTeam = catIdList
    for i = 1, #catTeam do
        local catData = self:GetCatData(catTeam[i])
        for j = 1, #extraCondition do
            local requireData = extraCondition[j]
            local isFinished = self:CheckCatIsSatisfyTaskExtraCondition(requireData.type, requireData.value, catData)
            if isFinished then
                return true
            end
        end
    end
    return false
end

function CatHouseExploreMgr:GetFinishedExtraCondition(exploreId, taskId)
    local listFinishedIndex = {}
    local catTeam = self.listCatsTeam
    local extraCondition = checkTable(self:GetRequireDataByIndex(checkTable(self:GetExploreRequireData(exploreId)), checkNumber(taskId)))
    for i = 1, #catTeam do
        local catData = catTeam[i]
        for j = 1, #extraCondition do
            local requireData = extraCondition[j]
            local isFinished = self:CheckCatIsSatisfyTaskExtraCondition(requireData.type, requireData.value, catData)
            if  isFinished and (not table.isContain(listFinishedIndex, j)) then
                table.insert(listFinishedIndex, j)
            end
        end
    end
    return listFinishedIndex
end

function CatHouseExploreMgr:GetCatSatisfyTaskExtraCondition(requireData, catData)
    local result = {}
    for i, data in pairs(requireData) do
        local requireId = data.type
        local value = data.value
        if requireId == ExploreExtraType.CatType then
            --- 检查猫类型
            if checkNumber(value) == checkNumber(catData.catId) then
                if not table.isContain(result,requireId) then
                    table.insert(result, requireId)
                end
            end
        end
        if requireId == ExploreExtraType.SpecifyBasic or requireId == ExploreExtraType.SpecifyCombination then
            --- 检查指定基因
            value = checkNumber(value)
            local genes = catData.genes
            for j, v in ipairs(genes) do
                local geneId = checkNumber(v.geneId)
                if value == geneId then
                    if not table.isContain(result,requireId) then
                        table.insert(result, requireId)
                    end
                end
            end
        end
        if requireId == ExploreExtraType.OwnBasic
                or requireId == ExploreExtraType.OwnCombination
                or requireId == ExploreExtraType.OwnVariation
                or requireId == ExploreExtraType.OwnPart
        then
            --- 检查指定大类
            local typeValue = checkNumber(self:GetKindTypeBySpecialId(requireId))
            local genes = catData.genes
            for k, v in ipairs(genes) do
                ---@type CatHouseCatDataVo
                local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", v.geneId)
                if checkNumber(catGeneData.kind) == typeValue then
                    if not table.isContain(result,requireId) then
                        table.insert(result, requireId)
                    end
                end
            end
        end
    end
    return result
end

function CatHouseExploreMgr:CheckCatIsSatisfyTaskExtraCondition(requireId, value, catData)
    requireId = checkNumber(requireId)
    if requireId == ExploreExtraType.CatType then
        --- 检查猫类型
        return checkNumber(value) == checkNumber(catData.catId)
    elseif requireId == ExploreExtraType.SpecifyBasic or requireId == ExploreExtraType.SpecifyCombination then
        --- 检查指定基因
        value = checkNumber(value)
        local genes = catData.genes
        for i, v in ipairs(genes) do
            local geneId = checkNumber(v.geneId)
            if value == geneId then
                return true
            end
        end
    elseif requireId == ExploreExtraType.OwnBasic
            or requireId == ExploreExtraType.OwnCombination
            or requireId == ExploreExtraType.OwnVariation
            or requireId == ExploreExtraType.OwnPart 
    then
        --- 检查指定大类
        local typeValue = checkNumber(self:GetKindTypeBySpecialId(requireId))
        local genes = catData.genes
        for i, v in ipairs(genes) do
            ---@type CatHouseCatDataVo
            local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", v.geneId)
            if checkNumber(catGeneData.kind) == typeValue then
                return true 
            end
        end
    end
    return false
end

function CatHouseExploreMgr:GetKindTypeBySpecialId(typeId)
    typeId = checkNumber(typeId)
    if typeId == ExploreExtraType.OwnBasic then
        return ConstantsCatHouse.ScreenCatDataType.Basic
    elseif typeId == ExploreExtraType.OwnCombination then
        return ConstantsCatHouse.ScreenCatDataType.Combination
    elseif typeId == ExploreExtraType.OwnVariation then
        return ConstantsCatHouse.ScreenCatDataType.Variation
    elseif typeId == ExploreExtraType.OwnPart then
        return ConstantsCatHouse.ScreenCatDataType.Part
    end
end


function CatHouseExploreMgr:FunctionOnBtnAutoFormation(exploreId)
    self.listCatsTeam = nil
    self.listCatsTeam = {}
    local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
    local catList = CatHouseMgr:GetInstance():FilterCatListByActionLimit(ConstantsCatHouse.CatActionType.Explore, nil, nil)
    local taskId = checkNumber(self:GetExploreData(exploreId).taskId)
    local taskData = self:GetCatHouseTaskData(taskId)
    local attributeId = checkString(taskData.attributeId)
    local requireData = self:GetRequireDataByIndex(checkTable(self:GetExploreRequireData(exploreId)), taskId)
    local listAttributeCondition = self:GetTaskAttributeCondition(taskId)
    local attributeValueMax = checkNumber(listAttributeCondition[#listAttributeCondition].numLevel)
    print("->CatHouseExploreMgr:FunctionOnBtnAutoFormation_attributeValueMax:", attributeValueMax)
    
    local _catIsInList = function(aimList, catData)
        for i, data in pairs(aimList) do
            local cat = data
            local catId = checkNumber(cat.id)
            if checkNumber(catData.id) == catId then
                return true
            end
        end
        return false
    end
    
    local numAttribute = 0
    local listExtra = {}
    local listCommon = {}
    if requireData and #requireData > 0 then
        for i = 1, #catList do
            local catData = catList[i]
            local isFinished = #checkTable(self:GetCatSatisfyTaskExtraCondition(requireData, catData)) > 0
            local aimList = isFinished and listExtra or listCommon
            if (not _catIsInList(listExtra, catData)) and (not _catIsInList(listCommon, catData))  then
                table.insert(aimList, catData)
            end
        end
    else
        listCommon = catList
    end
    
    if listExtra and #listExtra > 0 then
        table.sort(listExtra, function(a, b)
            local _aFinishStatus = self:GetCatSatisfyTaskExtraCondition(requireData, a)
            local _bFinishStatus = self:GetCatSatisfyTaskExtraCondition(requireData, b)
            return checkNumber(#_aFinishStatus) > checkNumber(#_bFinishStatus)
        end)
    end

    if listCommon and #listCommon > 0 then
        table.sort(listCommon, function(a, b)
            return checkNumber(a.attr[attributeId]) > checkNumber(b.attr[attributeId])
        end)
    end
    
    print("->CatHouseExploreMgr:FunctionOnBtnAutoFormation_listExtra:", table.dump(checkTable(listExtra)))
    print("->CatHouseExploreMgr:FunctionOnBtnAutoFormation_listCommon:", table.dump(checkTable(listCommon)))
    --self.extraConditionFinishedList = checkTable(CatHouseExploreMgr:GetFinishedExtraCondition(self.exploreId, self.taskData.taskId))
    
    local _extraConditions = {}
    local _listSelected = {}
    for i = 1, #listExtra do
        local isInsert = false
        local catData = listExtra[i]
        local catExtraConditions = self:GetCatSatisfyTaskExtraCondition(requireData, catData)
       
        for j, condition in pairs(catExtraConditions) do
            if not table.isContain(_extraConditions, condition) then
                isInsert = true
                table.insert(_extraConditions, condition)
            end
        end
        if isInsert then
            table.insert(self.listCatsTeam, catData)
            table.insert(_listSelected, checkNumber(catData.id))
            --print("->CatHouseExploreMgr:FunctionOnBtnAutoFormation_SelectedCats_ExtraConditions:", table.dump(catExtraConditions))
            numAttribute = numAttribute + checkNumber(catData.attr[attributeId])
            if #self.listCatsTeam >= self.EXPLORE_TEAM_CAT_MAX or numAttribute >= attributeValueMax then
                return self.listCatsTeam
            end
        end
    end

    for i = 1, #listCommon do
        local catData = listCommon[i]
        table.insert(self.listCatsTeam, catData)
        table.insert(_listSelected, checkNumber(catData.id))
        numAttribute = numAttribute + checkNumber(catData.attr[attributeId])
        if #self.listCatsTeam >= self.EXPLORE_TEAM_CAT_MAX or numAttribute >= attributeValueMax then
            return self.listCatsTeam
        end
    end

    --- 最后筛查一次，确保属性分最大化
    if catList and #catList > 0 then
        table.sort(catList, function(a, b)
            return checkNumber(a.attr[attributeId]) > checkNumber(b.attr[attributeId])
        end)
    end
    
    for i = 1, #catList do
        local catData = catList[i]
        if table.isContain(_listSelected, checkNumber(catData.id)) then
            goto continue
        end
        table.insert(self.listCatsTeam, catData)
        numAttribute = numAttribute + checkNumber(catData.attr[attributeId])
        if #self.listCatsTeam >= self.EXPLORE_TEAM_CAT_MAX or numAttribute >= attributeValueMax then
            return self.listCatsTeam
        end
        :: continue ::
    end

    return self.listCatsTeam
end

function CatHouseExploreMgr:GetExploreBoxServicesData()
    local catHouseHomeDojo = self:GetCatHouseHomeDojo()
    return checkNumber(catHouseHomeDojo.exploreBoxId), checkNumber(catHouseHomeDojo.exploreBoxProgress)
end

function CatHouseExploreMgr:GetExploreCellStatus()
    if isNull(self.listTaskData) then return false end
    for i = 1, #self.listTaskData do
        local exploreData = self.listTaskData[i]
        local exploreStatus = checkNumber(exploreData.status)
        if exploreStatus == ENUM_TASK_STATUS.FINISH then
            return true
        end
    end
    return false
end

function CatHouseExploreMgr:HandleTimerTaskRefresh()
    if isNull(self:GetCatHouseHomeDojo()) or #checkTable(self:GetCatHouseHomeDojo()) < 0 then return end
    local exploreRefreshTimes = checkNumber(self:GetCatHouseHomeDojo().exploreRefreshTimes)
    if exploreRefreshTimes < self.EXPLORE_REFRESH_TIME_MAX then
        self:GetCatHouseHomeDojo().exploreRefreshTimes = exploreRefreshTimes + 1
    end
    self:SetTimerTaskRefresh()
    Events.Broadcast(Constants.EventNames.CatHouseExploreTaskRefreshUpdate)
end

function CatHouseExploreMgr:SetTimerTaskRefresh()
    if checkNumber(self:GetCatHouseHomeDojo().exploreRefreshTimes) <  self.EXPLORE_REFRESH_TIME_MAX then
        self:GetCatHouseHomeDojo().exploreNextRefreshTimesSeconds = self.EXPLORE_REFRESH_TIME_LENGTH
        self.timerTaskRefresh = self:SetTimer(self.EXPLORE_REFRESH_TIME_LENGTH, nil, function()
            self.timerTaskRefresh = nil
            self:HandleTimerTaskRefresh()
        end)
    end
end

function CatHouseExploreMgr:SortCatsByAttributeType(catList, attributeId, asc)
    catList = checkTable(catList)
    asc = checkBool(asc)
    local t = clone(catList)
    local Checker = function(a, b, field, fieldIndex)
        --print("->CatHouseExploreMgr:SortCatsByAttributeType_CompareElement:", table.dump(a), table.dump(b), field, fieldIndex)
        local aFiled, bFiled = checkNumber(a[field][fieldIndex]), checkNumber(b[field][fieldIndex])
        if aFiled ~= bFiled  then
            if asc then
                return aFiled > bFiled
            else
                return aFiled < bFiled
            end
        end
    end
    table.sort(t, function(a, b)
        return Checker(a, b, "attr", attributeId)
    end)
    return t
end

function CatHouseExploreMgr:GetRedPointLeftTime()
    local leftTime
    for i, data in pairs(self.listTaskData) do
        local timerRemain = data.timerRemain
        if not IsNull(timerRemain) then
            local countTimes = checkNumber(timerRemain.CountTimes)
            if isNull(leftTime) then
                leftTime = countTimes
            else
                leftTime = countTimes <= checkNumber(leftTime) and countTimes or leftTime
            end
        end
    end
    return checkNumber(leftTime)
end

return CatHouseExploreMgr